        "type": "text",
        "content": "{\"entries\":[{\"id\":\"R1\",\"proposition\":\"Das Kundenportal soll als Web-Portal realisiert werden, mobile Nutzung ist später möglich.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Frontend\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0001: Also wir brauchen definitiv ein Kundenportal. ... Web first. Mobile später.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Mobile Nutzung unklar für MVP\",\"sourceUnitIds\":[\"AU-0001\"]},{\"id\":\"R2\",\"proposition\":\"Login erfolgt per E-Mail und Passwort mit Double-Opt-In zur DSGVO-Konformität.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Authentication\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0003: ...Login per E-Mail? Dann brauchen wir Double-Opt-In.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: MVP: 1. Login mit Double-Opt-In\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"high\",\"notes\":\"DSGVO-konformität zwingend\",\"sourceUnitIds\":[\"AU-0003\",\"AU-0199\"]},{\"id\":\"R3\",\"proposition\":\"Es wird ein Rollen- und Berechtigungskonzept mit mindestens den Rollen Admin, Sales und Kunde umgesetzt.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Authorization\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0064: Und ein Rollen- und Berechtigungskonzept.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 4. Rollen Admin/Sales/Kunde\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"high\",\"notes\":\"Support-Rolle im MVP ausgeschlossen\",\"sourceUnitIds\":[\"AU-0064\",\"AU-0199\"]},{\"id\":\"R4\",\"proposition\":\"Angebote sollen erstellt werden mit SAP-Lesedaten, jedoch ohne manuelle Sonderrabatte im MVP.\",\"kind\":\"constraint\",\"status\":\"decided\",\"modality\":\"must_not\",\"scope\":\"OfferManagement\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0203: Das wäre eine Constraint: keine manuellen Sonderrabatte im MVP.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 2. Angebotserstellung mit SAP-Lesedaten\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"high\",\"notes\":\"Sonderrabatte ohne Freigabe ausgeschlossen\",\"sourceUnitIds\":[\"AU-0199\",\"AU-0203\"]},{\"id\":\"R5\",\"proposition\":\"Rechnungen sollen im Kundenportal zum Download bereitgestellt werden.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"InvoiceManagement\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0111: Kunden sollen ... Rechnungen downloaden.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 3. Rechnungsdownload\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"medium\",\"notes\":\"Basisfunktionalität\",\"sourceUnitIds\":[\"AU-0111\",\"AU-0199\"]},{\"id\":\"R6\",\"proposition\":\"Das Backend muss eine API-Schicht bereitstellen, um Integration zu ermöglichen.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Backend\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0036: Wir brauchen definitiv eine API Layer.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"API Gateway Integration noch offen\",\"sourceUnitIds\":[\"AU-0036\"]},{\"id\":\"R7\",\"proposition\":\"Das Kundenportal muss DSGVO-konform sein, inklusive Auditierbarkeit, Löschkonzept und Datenresidenz in der EU.\",\"kind\":\"compliance_constraint\",\"status\":\"required\",\"modality\":\"must\",\"scope\":\"Compliance\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0003: DSGVO ... Double-Opt-In, Logging, Löschkonzepte, Auftragsverarbeitungsverträge.\"},{\"source\":\"transcript\",\"quote\":\"AU-0031: EU only?\"},{\"source\":\"transcript\",\"quote\":\"AU-0098: Wir brauchen nachweisbare Datenresidenz.\"},{\"source\":\"transcript\",\"quote\":\"AU-0259: DSGVO ist nicht optional.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"DSGVO zwingend, EU-Datenhosting bevorzugt\",\"sourceUnitIds\":[\"AU-0003\",\"AU-0031\",\"AU-0098\",\"AU-0259\"]},{\"id\":\"R8\",\"proposition\":\"Ein minimaler Audit Trail muss implementiert werden, der protokolliert, wer wann welche Angebote geöffnet oder geändert hat.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Security\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0023: Auditierbarkeit ist Pflicht.\"},{\"source\":\"transcript\",\"quote\":\"AU-0096: Und protokollieren. Wer hat welches Angebot geöffnet?\"},{\"source\":\"transcript\",\"quote\":\"AU-0166: Dann brauchen wir Event-History oder Audit-Log pro Angebot.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 5. Minimaler Audit Trail\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"high\",\"notes\":\"Audit Trail für Compliance und Nachvollziehbarkeit\",\"sourceUnitIds\":[\"AU-0023\",\"AU-0096\",\"AU-0166\",\"AU-0199\"]},{\"id\":\"R9\",\"proposition\":\"Das Hosting der Daten muss in der EU erfolgen oder zumindest DSGVO-konform sein, mit nachweisbarer Datenresidenz.\",\"kind\":\"compliance_constraint\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Infrastructure\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0032: Ja EU only. Oder zumindest DSGVO-konform.\"},{\"source\":\"transcript\",\"quote\":\"AU-0098: Wir brauchen nachweisbare Datenresidenz.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 6. EU Managed Hosting\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"EU-Datenhosting bevorzugt, Kostenrisiko vorhanden\",\"sourceUnitIds\":[\"AU-0032\",\"AU-0098\",\"AU-0199\"]},{\"id\":\"R10\",\"proposition\":\"Backup und Disaster Recovery sind für das MVP erforderlich.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Infrastructure\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0045: Wenn Kundendaten drin sind: ja.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: 7. Backup\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"medium\",\"notes\":\"Backup für Kundendaten verpflichtend\",\"sourceUnitIds\":[\"AU-0045\",\"AU-0199\"]},{\"id\":\"R11\",\"proposition\":\"OAuth wird als bevorzugtes Authentifizierungsverfahren für die API-Sicherheit betrachtet, ist aber noch nicht final entschieden.\",\"kind\":\"open_question\",\"status\":\"open\",\"modality\":\"must_consider\",\"scope\":\"Security\",\"timeScope\":\"mvp_or_later_unclear\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0258: Und OAuth ist bevorzugt, aber noch nicht final.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"OAuth vs API Keys noch offen\",\"sourceUnitIds\":[\"AU-0258\"]},{\"id\":\"R12\",\"proposition\":\"Support wird im MVP nur über ein Kontaktformular ohne Ticketpersistenz realisiert, was ein Risiko für Datenschutz und Supporteffizienz darstellt.\",\"kind\":\"risk\",\"status\":\"open\",\"modality\":\"must_note\",\"scope\":\"Support\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0206: Kontaktformular ohne Ticketpersistenz?\"},{\"source\":\"transcript\",\"quote\":\"AU-0211: Notieren als Risiko.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Supportprozess unklar, Datenschutzrisiko durch E-Mail\",\"sourceUnitIds\":[\"AU-0206\",\"AU-0211\"]},{\"id\":\"R13\",\"proposition\":\"Das MVP umfasst keine Freigabeprozesse für Rabatte; diese werden in einer späteren Phase umgesetzt.\",\"kind\":\"open_question\",\"status\":\"open\",\"modality\":\"must_note\",\"scope\":\"OfferManagement\",\"timeScope\":\"later_possible\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0201: Vielleicht Phase 2.\"},{\"source\":\"transcript\",\"quote\":\"AU-0199: Rabatt-Freigabe nicht im MVP\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"risks\":{\"applicability\":\"optional\",\"representationMode\":\"open_decision\"},\"open-questions\":{\"applicability\":\"required\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Freigabeprozess offen\",\"sourceUnitIds\":[\"AU-0201\",\"AU-0199\"]},{\"id\":\"R14\",\"proposition\":\"SAP-Verfügbarkeit ist eine kritische Abhängigkeit für das Kundenportal und muss berücksichtigt werden.\",\"kind\":\"risk\",\"status\":\"decided\",\"modality\":\"must_note\",\"scope\":\"Backend\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0246: Bitte schreibt \\\"SAP-Verfügbarkeit ist kritische Abhängigkeit\\\".\"}],\"disposition\":{\"requirements\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"risk_reference\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"not_applicable\",\"representationMode\":\"consciously_omitted\"}},\"riskLevel\":\"high\",\"notes\":\"SAP-Ausfall beeinträchtigt Angebotserstellung\",\"sourceUnitIds\":[\"AU-0246\"]},{\"id\":\"R15\",\"proposition\":\"Es wird ein minimaler Retention-Plan für Angebotsdaten benötigt, der gesetzliche Aufbewahrungspflichten und Löschanfragen berücksichtigt.\",\"kind\":\"requirement\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"Compliance\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0191: Okay, minimaler Retention-Plan.\"},{\"source\":\"transcript\",\"quote\":\"AU-0185: Recht auf Löschung kollidiert mit Aufbewahrungspflichten.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"requirement\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"high\",\"notes\":\"Rechtliche Anforderungen beachten\",\"sourceUnitIds\":[\"AU-0191\",\"AU-0185\"]},{\"id\":\"R16\",\"proposition\":\"Das MVP muss klar definieren, was enthalten ist, was bewusst ausgeschlossen wird und welche Risiken dadurch entstehen.\",\"kind\":\"process_constraint\",\"status\":\"decided\",\"modality\":\"must\",\"scope\":\"ProjectManagement\",\"timeScope\":\"mvp\",\"evidence\":[{\"source\":\"transcript\",\"quote\":\"AU-0262: Dann ist das finale Ziel für jetzt: ein MVP-Schnitt, der klar sagt, was drin ist, was bewusst ausgeschlossen ist und welche Risiken dadurch entstehen.\"}],\"disposition\":{\"requirements\":{\"applicability\":\"required\",\"representationMode\":\"constraint\"},\"architecture\":{\"applicability\":\"optional\",\"representationMode\":\"assumption\"},\"risks\":{\"applicability\":\"required\",\"representationMode\":\"risk_reference\"},\"open-questions\":{\"applicability\":\"optional\",\"representationMode\":\"question\"}},\"riskLevel\":\"medium\",\"notes\":\"Klare Scope-Definition für MVP\",\"sourceUnitIds\":[\"AU-0262\"]}]}"
      }
    ],
    "finish_reason": "stop"
  }
]

tags.gen_ai.input.messages:
[
  {
    "role": "system",
    "parts": [
      {
        "type": "text",
        "content": "Du sichtest Atomic Units, die von keinem Candidate Claim direkt referenziert wurden.

Ziel dieses Schritts ist NUR Triage, kein Ledger-Vergleich.
Entscheide grob, ob eine Unit offensichtlich irrelevant/noise ist oder potenziell fachlich relevant sein kann.

Markiere konservativ:
- Wenn die Unit eine konkrete SDLC-relevante Aussage, Frage, Unsicherheit, Entscheidung, Constraint,
  Risiko, fachliche Regel, Compliance-Aussage, Architekturhinweis oder Scope-Aussage enthaelt:
  triage = potentially_relevant.
- Wenn sie nur Zustimmung, Rueckfrage ohne Inhalt, Gespraechsfuellung oder reine Wiederholung ist:
  triage = acknowledgement | smalltalk | low_signal | repetition.
- Wenn unklar: potentially_relevant.

Erlaubte triage-Werte:
trash
smalltalk
acknowledgement
repetition
low_signal
potentially_relevant

Antworte ausschliesslich mit JSON:
{
  "items": [
    {
      "unitId": "AU-0001",
      "triage": "potentially_relevant|low_signal|repetition|acknowledgement|smalltalk|trash",
      "reason": "kurz",
      "keywords": ["SAP", "Rabattlogik"]
    }
  ]
}"
      }
    ]
  },
  {
    "role": "user",
    "parts": [
      {
        "type": "text",
        "content": "{
  "unusedUnits": [
    {
      "id": "AU-0002",
      "speaker": "Ben",
      "text": "Moment, mobile hei\u00DFt native App oder responsive Web? Weil native w\u00E4re teuer. Und wir haben eigentlich kein Budget f\u00FCr zwei Frontends. Und ehrlich gesagt ist unser Backend noch nicht mal API-ready."
    },
    {
      "id": "AU-0004",
      "speaker": "Anna",
      "text": "Ja aber das darf uns jetzt nicht blockieren. MVP in 8 Wochen wurde versprochen. Also erstmal Login per E-Mail und Passwort. SSO w\u00E4re sch\u00F6n. Vielleicht Azure AD. Oder Google? Oder beides?"
    },
    {
      "id": "AU-0005",
      "speaker": "Ben",
      "text": "Moment, SSO hei\u00DFt Identity Provider Integration. Wir haben kein zentrales IAM. SAP hat irgendwas, aber das ist uralt."
    },
    {
      "id": "AU-0006",
      "speaker": "Clara",
      "text": "SAP? Wenn SAP involviert ist, dann reden wir von personenbezogenen Daten im ERP. Dann brauchen wir Audit Trails. Und Zugriffskontrolle. Und Rollenmodelle."
    },
    {
      "id": "AU-0007",
      "speaker": "Anna",
      "text": "Ja Rollen. Admin und normaler User. Vielleicht noch Manager. Und Support. Oder brauchen wir Support? Wer pflegt eigentlich Stammdaten?"
    },
    {
      "id": "AU-0008",
      "speaker": "Ben",
      "text": "Stammdaten liegen in SAP. Aber die sind teilweise unvollst\u00E4ndig. Also wenn wir Angebote generieren wollen \u2013 was Sales unbedingt will \u2013 dann brauchen wir Produktdaten, Preise, Rabattlogik."
    },
    {
      "id": "AU-0009",
      "speaker": "Anna",
      "text": "Ja genau! Angebote schneller erstellen. Das ist eigentlich das Hauptziel. Portal ist nur Mittel zum Zweck."
    },
    {
      "id": "AU-0010",
      "speaker": "Clara",
      "text": "Moment, ich dachte es geht um Rechnungsdownload?"
    },
    {
      "id": "AU-0011",
      "speaker": "Anna",
      "text": "Ja auch. Also Kunden sollen Bestellungen sehen und Rechnungen downloaden. Aber Sales will Angebote erstellen. Und Marketing will Push Notifications."
    },
    {
      "id": "AU-0012",
      "speaker": "Ben",
      "text": "Push Notifications? Das hatten wir nie besprochen."
    },
    {
      "id": "AU-0013",
      "speaker": "Anna",
      "text": "Doch, im letzten Meeting. Also ich glaube zumindest."
    },
    {
      "id": "AU-0014",
      "speaker": "Clara",
      "text": "Push hei\u00DFt Einwilligung. Wieder DSGVO. Und Tracking ist auch ein Thema."
    },
    {
      "id": "AU-0015",
      "speaker": "Ben",
      "text": "Tracking? Wir haben keine Analytics Infrastruktur."
    },
    {
      "id": "AU-0016",
      "speaker": "Anna",
      "text": "Brauchen wir aber vielleicht sp\u00E4ter. Also nicht im MVP. Oder doch? Wir m\u00FCssen KPIs messen."
    },
    {
      "id": "AU-0017",
      "speaker": "Ben",
      "text": "Was sind die KPIs?"
    },
    {
      "id": "AU-0018",
      "speaker": "Anna",
      "text": "Conversion Rate. Angebot \u2192 Bestellung. Und Zeit bis Angebot."
    },
    {
      "id": "AU-0019",
      "speaker": "Clara",
      "text": "Zeit bis Angebot ist kein personenbezogenes Datum. Das ist gut."
    },
    {
      "id": "AU-0020",
      "speaker": "Ben",
      "text": "Aber Angebot selbst enth\u00E4lt personenbezogene Daten."
    },
    {
      "id": "AU-0021",
      "speaker": "Anna",
      "text": "Also brauchen wir Verschl\u00FCsselung. Ende-zu-Ende? Oder reicht TLS?"
    },
    {
      "id": "AU-0022",
      "speaker": "Ben",
      "text": "TLS reicht. E2E ist unrealistisch."
    },
    {
      "id": "AU-0024",
      "speaker": "Anna",
      "text": "Ja Logging. Aber bitte nicht zu komplex. Wir haben keine Zeit."
    },
    {
      "id": "AU-0025",
      "speaker": "Ben",
      "text": "Security Review dauert 6 Wochen. Das sprengt die 8 Wochen MVP."
    },
    {
      "id": "AU-0026",
      "speaker": "Anna",
      "text": "Dann machen wir es ohne Security Review?"
    },
    {
      "id": "AU-0027",
      "speaker": "Clara",
      "text": "Das ist keine Option."
    },
    {
      "id": "AU-0028",
      "speaker": "Ben",
      "text": "Vielleicht k\u00F6nnen wir Managed Services nehmen. Kein neuer DB Server \u2013 IT hat das klar gesagt."
    },
    {
      "id": "AU-0029",
      "speaker": "Anna",
      "text": "Ja kein neuer DB Server. Managed Services sind okay. Aber bitte g\u00FCnstig."
    },
    {
      "id": "AU-0030",
      "speaker": "Ben",
      "text": "G\u00FCnstig und skalierbar widerspricht sich."
    },
    {
      "id": "AU-0033",
      "speaker": "Ben",
      "text": "Das ist nicht dasselbe."
    },
    {
      "id": "AU-0034",
      "speaker": "Clara",
      "text": "Genau."
    },
    {
      "id": "AU-0035",
      "speaker": "Anna",
      "text": "Okay also: - Kundenportal - Angebote - Rechnungen - Login - Rollen - Logging - SAP Integration - Keine neue DB - MVP in 8 Wochen - Security Review irgendwie - DSGVO - KPIs - Mobile vielleicht - SSO optional - API Layer?"
    },
    {
      "id": "AU-0037",
      "speaker": "Clara",
      "text": "API muss abgesichert sein. OAuth? Oder API Keys?"
    },
    {
      "id": "AU-0038",
      "speaker": "Ben",
      "text": "OAuth w\u00E4re besser. Aber komplexer."
    },
    {
      "id": "AU-0039",
      "speaker": "Anna",
      "text": "Komplexer hei\u00DFt mehr Zeit."
    },
    {
      "id": "AU-0040",
      "speaker": "Ben",
      "text": "Ja."
    },
    {
      "id": "AU-0041",
      "speaker": "Clara",
      "text": "Und wir haben noch gar nicht \u00FCber Backup gesprochen."
    },
    {
      "id": "AU-0042",
      "speaker": "Anna",
      "text": "Backup?"
    },
    {
      "id": "AU-0043",
      "speaker": "Ben",
      "text": "Ja Disaster Recovery."
    },
    {
      "id": "AU-0044",
      "speaker": "Anna",
      "text": "Brauchen wir das f\u00FCr MVP?"
    },
    {
      "id": "AU-0046",
      "speaker": "Anna",
      "text": "Okay also doch."
    },
    {
      "id": "AU-0047",
      "speaker": "Ben",
      "text": "Und Performance. Wie viele User erwarten wir?"
    },
    {
      "id": "AU-0048",
      "speaker": "Anna",
      "text": "Wei\u00DF ich nicht. Vielleicht 200. Vielleicht 2000. Vielleicht 20.000 wenn es gut l\u00E4uft."
    },
    {
      "id": "AU-0049",
      "speaker": "Ben",
      "text": "Das ist ein Unterschied."
    },
    {
      "id": "AU-0050",
      "speaker": "Clara",
      "text": "Skalierbarkeit muss ber\u00FCcksichtigt werden."
    },
    {
      "id": "AU-0051",
      "speaker": "Anna",
      "text": "Aber bitte kein Overengineering."
    },
    {
      "id": "AU-0052",
      "speaker": "Ben",
      "text": "Overengineering und skalierbar sind ein Spannungsfeld."
    },
    {
      "id": "AU-0053",
      "speaker": "Anna",
      "text": "Wir drehen uns im Kreis."
    },
    {
      "id": "AU-0054",
      "speaker": "Clara",
      "text": "Und wir haben noch keine klare Zieldefinition."
    },
    {
      "id": "AU-0055",
      "speaker": "Anna",
      "text": "Ziel ist schneller Angebote erstellen."
    },
    {
      "id": "AU-0056",
      "speaker": "Ben",
      "text": "Und Portal."
    },
    {
      "id": "AU-0057",
      "speaker": "Clara",
      "text": "Und Compliance."
    },
    {
      "id": "AU-0058",
      "speaker": "Anna",
      "text": "Ja. (Stille)"
    },
    {
